# Adapted from https://github.com/shrx/spectre/blob/master/spectre.py

import drawsvg as draw
import numpy as np
from time import time

num_tiles = 0

IDENTITY = [1, 0, 0, 0, 1, 0]

TILE_NAMES = ["Gamma", "Delta", "Theta", "Lambda", "Xi", "Pi", "Sigma", "Phi", "Psi"]

